const h = $input.first().json.headers || {};
const total = Number(h["x-pagination-total-count"] || 0);
if (!total) { throw new Error("No pagination header"); }
const limit = 500;
const pages = Math.ceil(total / limit);
const out = [];
const langs = [640, 757];
for (const lid of langs) {
  for (let p = 1; p <= pages; p++) { out.push({ json: { lang_id: lid, page: p, limit: limit } }); }
}
return out;

const BATCH_SIZE = 10;
const BATCH_LIMIT = 250;

const LOCKED = [
  ['The King', 'Raja'],
  ['The Queen', 'Ratu'],
  ['The Warrior', 'Ksatria'],
  ['The Lover', 'Pencinta'],
  ['The Sage', 'Cendekiawan'],
  ['The Rebel', 'Pemberontak'],
  ['The Provider', 'Pencari Nafkah'],
  ['The Explorer', 'Penjelajah'],
  ['The Craftsman', 'Perajin'],
  ['The Maiden', 'Putri'],
  ['The Nurturer', 'Penyayang'],
  ['The Mystic', 'Mistikus'],
  ['The Starter', 'Penggagas'],
  ['The Finisher', 'Penyelesai'],
  ['The Optimizer', 'Pengoptimal'],
  ['The Stabilizer', 'Penstabil'],
  ['The Problem Solver', 'Pemecah Masalah'],
  ['The Executor', 'Pelaksana'],
  ['The Adapter', 'Penyesuai'],
  ['The Deep Worker', 'Pekerja Fokus'],
  ['Neurodivergence', 'Neurodivergensi'],
  ['Sociopath', 'Sosiopat'],
  ['Psychopath', 'Psikopat'],
  ['Empath', 'Empati']
];
const locked = [];
for (const p of LOCKED) { locked.push({ en: p[0], ms: p[1] }); }
function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

const gPages = [$('Fetch glossary').first().json, $('Fetch glossary page 2').first().json];
const seenTerm = {};
const gloss = [];
let rawCount = 0;
for (const pg of gPages) {
  if (!pg || !Array.isArray(pg.data)) { continue; }
  for (const t of pg.data) {
    rawCount = rawCount + 1;
    if (seenTerm[t.id] === 1) { continue; }
    seenTerm[t.id] = 1;
    if (t.translatable === false) { continue; }
    let v = '';
    if (Array.isArray(t.translations)) {
      for (const tr of t.translations) { if (tr.langIso === 'id') { v = String(tr.translation || '').trim(); } }
    }
    if (!v) { continue; }
    if (v.indexOf('\n') !== -1) { continue; }
    gloss.push({ en: String(t.term), ms: v, lc: String(t.term).toLowerCase() });
  }
}
if (gloss.length < 100) { throw new Error('Glossary looks too small: ' + gloss.length + ' of ' + rawCount + ' rows'); }

const pages = $input.all();
const en = {};
const tg = [];
for (const p of pages) {
  const j = p.json;
  if (!Array.isArray(j.rows)) { continue; }
  if (j.iso === 'en') { for (const r of j.rows) { en[r[0]] = r[1]; } }
  else { for (const r of j.rows) { tg.push({ k: r[0], text: r[1], tid: r[2], mt: r[3] }); } }
}

const targets = [];
let redo = 0;
for (const r of tg) {
  const src = en[r.k];
  if (src === undefined || String(src).trim() === '') { continue; }
  const cur = String(r.text).trim();
  if (cur === '') { targets.push({ tid: r.tid, en: String(src) }); continue; }
  if (r.mt !== 1) { continue; }
  let violates = false;
  for (const l of locked) {
    const inSrc = new RegExp('(^|[^A-Za-z])' + esc(l.en) + '([^A-Za-z]|$)', 'i');
    if (!inSrc.test(String(src))) { continue; }
    if (cur.toLowerCase().indexOf(l.ms.toLowerCase()) === -1) { violates = true; }
  }
  if (violates) { targets.push({ tid: r.tid, en: String(src) }); redo = redo + 1; }
}

const batches = [];
for (let i = 0; i < targets.length; i = i + BATCH_SIZE) {
  const slice = targets.slice(i, i + BATCH_SIZE);
  let blob = '';
  for (const s of slice) { blob = blob + ' ' + s.en.toLowerCase(); }
  const terms = [];
  for (const t of gloss) {
    if (blob.indexOf(t.lc) !== -1 && terms.length < 60) { terms.push(t.en + ' = ' + t.ms); }
  }
  batches.push({ json: { index: batches.length, segments: slice, glossary: terms, locked: locked, total_targets: targets.length, retranslate_for_locked_names: redo, glossary_size: gloss.length } });
  if (BATCH_LIMIT > 0 && batches.length >= BATCH_LIMIT) { break; }
}
return batches;

const items = $input.all();
let written = 0;
const skipped = [];
for (const it of items) {
  if (it.json.skipped) { skipped.push(it.json); } else if (it.json.translation) { written = written + 1; }
}
return [{ json: { written: written, skipped: skipped.length, skipped_detail: skipped.slice(0, 40) } }];

const PARTICLES = ['dan','atau','di','ke','dari','pada','untuk','yang','dengan','dalam','oleh','serta','bagi','kepada','terhadap','tentang','antara','karena','jika','tetapi','agar','supaya','daripada'];
const ALWAYS_CAPS = ['anda'];

function isAlphaWord(w) { return /[A-Za-z\u00c0-\u024f]/.test(w); }
function wordsOf(s) { return s.match(/[A-Za-z\u00c0-\u024f][A-Za-z\u00c0-\u024f'\u2019-]*/g) || []; }
function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function endsSentence(tok) { return /[.!?\n]/.test(tok) && /\s/.test(tok); }

function sourceCapWords(src) {
  const words = wordsOf(src);
  const set = {};
  for (let i = 1; i < words.length; i++) {
    const w = words[i];
    if (w[0] === w[0].toUpperCase() && w !== w.toUpperCase()) { set[w.toLowerCase()] = 1; }
  }
  return set;
}

function sourceTokens(src) {
  const set = {};
  for (const w of wordsOf(src)) { set[w] = 1; }
  return set;
}

function allCapsSource(src) {
  const words = wordsOf(src);
  if (words.length === 0) { return false; }
  for (const w of words) { if (w !== w.toUpperCase()) { return false; } }
  return true;
}

function up1(w) { return w.charAt(0).toUpperCase() + w.slice(1); }
function down1(w) { return w.charAt(0).toLowerCase() + w.slice(1); }

function forceCase(src, tgt) {
  if (wordsOf(src).length === 0) { return tgt; }
  const shouty = allCapsSource(src);
  const keep = sourceCapWords(src);
  const srcTok = sourceTokens(src);
  const tokens = tgt.split(/([^A-Za-z\u00c0-\u024f'\u2019-]+)/);
  let sentenceStart = true;
  const out = [];
  for (const tok of tokens) {
    if (!isAlphaWord(tok)) {
      out.push(tok);
      if (endsSentence(tok)) { sentenceStart = true; }
      continue;
    }
    const lc = tok.toLowerCase();
    const isShout = tok.length > 1 && tok === tok.toUpperCase();
    if (isShout && srcTok[tok] === 1 && !shouty) { out.push(tok); sentenceStart = false; continue; }
    const base = isShout ? lc : tok;
    if (ALWAYS_CAPS.indexOf(lc) !== -1) { out.push(up1(base)); sentenceStart = false; continue; }
    if (sentenceStart) { out.push(up1(base)); sentenceStart = false; continue; }
    if (PARTICLES.indexOf(lc) !== -1) { out.push(down1(base)); continue; }
    if (keep[lc] === 1 && !shouty) { out.push(base); continue; }
    out.push(down1(base));
  }
  return out.join('');
}

function tidy(s) {
  let t = String(s);
  t = t.replace(/\u00a0/g, ' ');
  t = t.replace(/\u200b/g, '');
  t = t.replace(/\u2011/g, '-');
  t = t.replace(/\u2026/g, '...');
  t = t.replace(/[\u201c\u201d]/g, '\"');
  t = t.replace(/[\u2018\u2019]/g, "'");
  t = t.replace(/[ \t]{2,}/g, ' ');
  return t.trim();
}

function fixFinalStop(src, tgt) {
  const s = src.trim();
  const words = s.split(/\s+/).length;
  const srcEnds = /[.!?:;]$/.test(s);
  if (!srcEnds && words <= 8 && /\.$/.test(tgt)) { return tgt.replace(/\.+$/, ''); }
  if (/\.$/.test(s) && !/[.!?:;]$/.test(tgt)) { return tgt + '.'; }
  return tgt;
}

function marks(s) {
  const found = String(s).match(/(\{[^}]*\}|\[%[^\]]*\]|%\d+\$[sd]|%[sd]|<\/?[A-Za-z][^>]*>)/g) || [];
  return found.sort().join('\u0001');
}

const batch = $('Loop batches').first().json;
const segs = batch.segments;
const glossary = batch.glossary || [];
const locked = batch.locked || [];

const raw = $input.first().json;
let content = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) { content = raw.choices[0].message.content || ''; }
if (!content) { throw new Error('No model content: ' + JSON.stringify(raw).slice(0, 400)); }
content = content.replace(/```json/g, '').replace(/```/g, '').trim();

let parsed = null;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('Model did not return JSON: ' + content.slice(0, 400)); }
if (!Array.isArray(parsed)) { throw new Error('Model JSON is not an array'); }

const byIndex = {};
for (const p of parsed) { if (p && p.i !== undefined) { byIndex[String(p.i)] = p.ms; } }

const out = [];
for (let n = 0; n < segs.length; n++) {
  const seg = segs[n];
  const rawMs = byIndex[String(n + 1)];
  const problems = [];
  const warnings = [];
  if (rawMs === undefined || String(rawMs).trim() === '') {
    out.push({ json: { valid: false, tid: seg.tid, en: seg.en, ms: '', problems: ['no translation returned'], warnings: [] } });
    continue;
  }

  const srcTrim = seg.en.trim();
  let exact = '';
  for (const l of locked) { if (srcTrim.toLowerCase() === l.en.toLowerCase()) { exact = l.ms; } }

  let t = '';
  if (exact) {
    t = exact;
  } else {
    t = tidy(rawMs);
    t = forceCase(seg.en, t);
    t = fixFinalStop(seg.en, t);
    for (const l of locked) {
      const inSrc = new RegExp('(^|[^A-Za-z])' + esc(l.en) + '([^A-Za-z]|$)', 'i');
      if (!inSrc.test(seg.en)) { continue; }
      t = t.replace(new RegExp(esc(l.ms), 'gi'), l.ms);
    }
    t = t.replace(/personality\.Co/g, 'personality.co');
    t = tidy(t);
  }

  if (marks(seg.en) !== marks(t)) { problems.push('placeholder or tag mismatch'); }
  if (t.toLowerCase() === seg.en.toLowerCase() && /[A-Za-z]{4,}/.test(seg.en)) { problems.push('untranslated - identical to source'); }
  if (/\b(kamu|engkau|e-mel|muat turun|muat naik|kata laluan|akaun|personaliti|seterusnya|tetapan)\b/i.test(t)) { problems.push('Malay form in Indonesian'); }
  for (const l of locked) {
    const inSrc = new RegExp('(^|[^A-Za-z])' + esc(l.en) + '([^A-Za-z]|$)', 'i');
    if (!inSrc.test(seg.en)) { continue; }
    if (t.toLowerCase().indexOf(l.ms.toLowerCase()) === -1) { problems.push('locked name missing: ' + l.en); }
  }
  const srcNoPunct = srcTrim.replace(/[.:;!?]+$/, '').trim().toLowerCase();
  for (const g of glossary) {
    const bits = g.split(' = ');
    if (bits.length !== 2) { continue; }
    const term = bits[0];
    const val = bits[1];
    if (t.toLowerCase().indexOf(val.toLowerCase()) !== -1) { continue; }
    if (srcNoPunct === term.toLowerCase()) { problems.push('glossary miss: ' + term); }
    else {
      const inSource = new RegExp('(^|[^A-Za-z])' + esc(term) + '([^A-Za-z]|$)', 'i');
      if (term.length >= 4 && inSource.test(srcTrim)) { warnings.push('glossary variance: ' + term); }
    }
  }

  out.push({ json: { valid: problems.length === 0, tid: seg.tid, en: seg.en, ms: t, problems: problems, warnings: warnings, payload: { translation: t, is_fuzzy: true, is_reviewed: false, custom_translation_status_ids: [29251] } } });
}
return out;

const out = [];
for (const it of $input.all()) { out.push({ json: { skipped: true, tid: it.json.tid, en: it.json.en, ms: it.json.ms, problems: it.json.problems } }); }
return out;

const t = $input.first().json.translations;
if (!Array.isArray(t)) { throw new Error("No translations array"); }
let iso = "";
const rows = [];
for (const x of t) {
  iso = x.language_iso;
  const val = x.translation === null || x.translation === undefined ? "" : String(x.translation);
  if (x.language_iso === "en") {
    rows.push([x.key_id + ":" + x.segment_number, val]);
  } else {
    let mt = 0;
    if (Array.isArray(x.custom_translation_statuses)) {
      for (const s of x.custom_translation_statuses) { if (s.status_id === 29251) { mt = 1; } }
    }
    rows.push([x.key_id + ":" + x.segment_number, val, x.translation_id, mt]);
  }
}
return [{ json: { iso: iso, rows: rows } }];
